with open(prog_path, 'w') as f:
    f.write('''# Continual-ARC transform: preserve top region, remap to 2
def transform(grid):
    # Find separator row (all same value after varied row)
    h, w = len(grid), len(grid[0])
    for i in range(h):
        if all(grid[i][j] == grid[i][j-1] for j in range(1, w)):
            if i > 0 and len(set(grid[i-1][j] for j in range(w))) > 1:
                sep_row = i
                break

    top = grid[:sep_row]
    result = [[0]*w for _ in range(len(top))]
    for r in range(len(top)):
        for c in range(w):
            result[r][c] = 2 if top[r][c] != 0 else 0
    return result
''')

